/* This module reads JSON locally and teaches contracts. It never connects to
 * the learner's ComfyUI, runs GPU work or installs a custom node. */
let cfPane='route',cfStage=cfLessonRows[0][1],cfSampleId='sdxl',cfDocument=null,cfGraphId='main',cfNodeId='',cfEdge=-1,cfQuery='',cfError='',cfLoading=false,cfLoadToken=0,cfOrigin='',cfHistoryAll=false,cfHistoryQuery='',cfTrace=[];
let cfCalculator={frames:81,fps:16,grid:'none',result:null,error:''},cfWire={source:'LATENT',target:'SaveImage.images',result:null};
const cfWireTargets=[['SaveImage.images','IMAGE'],['VAEDecode.samples','LATENT'],['CreateVideo.images','IMAGE'],['CreateVideo.audio','AUDIO'],['SaveVideo.video','VIDEO'],['KSampler.model','MODEL']];
const cfCache=new Map();
function cfGraph(){return cfDocument?.graphs.find(g=>g.id===cfGraphId)||cfDocument?.graphs[0];}
function cfNode(){return cfGraph()?.nodes.find(n=>n.id===cfNodeId);}
function cfInfo(n){if(n.boundary)return {name:n.title,does:'这是解析器显示的子图输入 / 输出契约边界。',why:'把外部端口与子图内部连线对应起来，继续追数据。',trap:'虚拟边界不计入实际运算节点，也不是需要安装的插件。',source:'core'};if(n.subgraph)return {name:n.title,does:'这一方块封装了 '+(cfDocument?.graphs.find(g=>g.id===n.subgraph)?.nodes.filter(x=>!x.boundary).length||0)+' 个内部节点。',why:'外部端口是子图的输入输出契约。展开后继续追到真正的加载、采样、解码或保存节点。',trap:'UUID 是已声明的子图类型，不应直接当作缺失插件。',source:'core'};return (Object.hasOwn(cfNodeInfo,n.type)?cfNodeInfo[n.type]:null)||{name:n.title,does:n.annotation?'这是说明便签，通常不参与模型计算。':'这个节点的职责尚未收录核实。下面保留文件声明的真实端口和连线。',why:'结构能说明谁给谁传数据；具体算法、单位和副作用还需要原插件文档或实现。',trap:'不根据翻译名或外观编造功能；解析成功也不证明本机已安装它。',source:null};}
function cfTypeHTML(t){const def=Object.hasOwn(cfTypes,t)?cfTypes[t]:null;return `<code class="cf-type">${esc(t)}</code>${def?`<span>${esc(def[0])}</span>`:''}`;}
function cfAccept(raw,origin){const parsed=ComfyLab.normalize(raw);cfDocument=parsed;cfGraphId='main';cfNodeId=cfGraph().nodes.find(n=>!n.annotation)?.id||cfGraph().nodes[0].id;cfEdge=-1;cfTrace=[];cfQuery='';cfOrigin=origin;cfError='';}
async function cfLoadSample(id){const sample=cfSamples.find(s=>s.id===id);if(!sample)return;const token=++cfLoadToken;cfSampleId=id;cfLoading=true;cfError='';render();try{let raw=cfCache.get(id);if(!raw){const response=await fetch('data/comfy/workflows/'+sample.file);if(!response.ok)throw Error('示例暂时无法加载，请稍后重试或导入本地 JSON。');raw=await response.json();cfCache.set(id,raw);}if(token!==cfLoadToken)return;cfAccept(raw,sample.title);const target=cfGraph().nodes.find(n=>n.id===sample.focus);if(target)cfNodeId=target.id;}catch(e){if(token===cfLoadToken)cfError=e.message;}finally{if(token===cfLoadToken){cfLoading=false;render();}}}
function cfOpen(pane='route',sample){cfPane=['route','inspect','practice','sources','trouble'].includes(pane)?pane:'route';hubSubject='comfy';view='subject';render();window.scrollTo({top:0,behavior:'instant'});if(sample)cfLoadSample(sample);else if(cfPane==='inspect'&&!cfDocument)cfLoadSample(cfSampleId);}
function cfTitle(){return {route:'ComfyUI 学习',inspect:'工作流逐节点拆解',practice:'连线与视频参数练习',sources:'UP 主与开源资料',trouble:'按现象定位问题'}[cfPane];}
function cfShell(content){const next=hubNextIndex('comfy'),c=hubCurriculum.comfy[next];return `<main class="hub-main cf-main"><div class="cf-heading"><div><h1>${cfTitle()}</h1><p>${cfPane==='route'?'先看懂一根线，再搭好一段视频。':cfPane==='inspect'?'选一个节点，读它收到什么、做了什么、交出什么。':'把条件、范围和验证方法讲清楚。'}</p></div><button class="secondary" data-hub="lesson" data-track="comfy" data-index="${next}">继续课程：${esc(c.title)}</button></div><nav class="cf-tabs" aria-label="ComfyUI 学习区">${[['route','学习路线'],['inspect','工作流解析'],['practice','连线 / 参数'],['sources','UP 主资料'],['trouble','故障排查']].map(([id,label])=>`<button type="button" data-cf-pane="${id}" ${cfPane===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav>${content}</main>`;}
function cfRouteHTML(){const done=hubState.completed.comfy,stages=[...new Set(cfLessonRows.map(r=>r[1]))],lessons=hubCurriculum.comfy.filter(c=>c.section===cfStage);return `<section class="cf-start"><div><h2>从会搭，到能解释</h2><p>每课先说用途与先备知识，再看完整的数据关系，最后自己判断。按建议顺序学，也可直接进入需要的视频课；每课仍要完成操作与小测。</p><p class="cf-scope">网页提供教学、连线检查与 JSON 静态解析。生成图片和视频需要你自己的 ComfyUI、模型与设备。</p><button class="primary" data-hub="lesson" data-track="comfy" data-index="${hubNextIndex('comfy')}">开始 / 继续学习</button></div><aside><h3>拿到别人的大工作流？</h3><p>先从输出往前追。展开子图，区分模型、条件、latent 和成品。</p><button class="secondary" data-cf-pane="inspect">打开结构示例解析</button><p>${done.length} / ${hubCurriculum.comfy.length} 课已通过 · 本设备记录</p></aside></section><div class="cf-route-layout"><nav class="cf-stage-list" aria-label="课程阶段">${stages.map((s,i)=>{const rows=hubCurriculum.comfy.filter(c=>c.section===s);return `<button type="button" data-cf-stage="${i}" ${s===cfStage?'aria-current="step"':''}><span>${i+1}. ${esc(s)}</span><small>${rows.filter(c=>done.includes(c.id)).length} / ${rows.length}</small></button>`;}).join('')}</nav><section class="cf-course-list"><h2>${esc(cfStage)}</h2>${lessons.map(c=>{const i=hubCurriculum.comfy.indexOf(c);return `<article class="cf-course-row"><div><h3>${esc(c.title)}</h3><p>${esc(c.summary)}</p><small>先备：${esc(c.novice.before)}</small></div><button class="${done.includes(c.id)?'secondary':'text-button'}" data-hub="lesson" data-track="comfy" data-index="${i}">${done.includes(c.id)?'复习这课':'学这一课 →'}</button></article>`;}).join('')}</section></div>`;}
function cfNodeListHTML(){const graph=cfGraph();if(!graph)return '';const rows=graph.nodes.filter(n=>(n.id+' '+n.type+' '+n.title+' '+cfInfo(n).name).toLowerCase().includes(cfQuery.toLowerCase()));return `<p class="cf-list-count">${rows.length} 条匹配${rows.some(n=>n.boundary)?'（含子图边界）':'节点'}${rows.length>80?' · 先显示 80 个，请继续搜索缩小范围':''}</p>${rows.slice(0,80).map(n=>`<button type="button" class="cf-node-row ${cfTrace.includes(n.id)?'cf-traced':''}" data-cf-node="${esc(n.id)}" ${n.id===cfNodeId?'aria-current="true"':''}><b>${esc(cfInfo(n).name)}</b><small>#${esc(n.id)} · ${esc(n.type)}${n.annotation?' · 说明':n.subgraph?' · 子图':''}${[2,4].includes(n.mode)?' · 禁用 / 绕过':''}</small></button>`).join('')||'<p>没有找到匹配节点。可用原始 class_type 或 ID 搜索。</p>'}`;}
function cfPortsHTML(n){return `<div class="cf-port-pair"><section><h3>输入：收到什么</h3>${n.inputs.length?`<ul>${n.inputs.map(p=>`<li><b>${esc(p.name)}</b>${cfTypeHTML(p.type)}</li>`).join('')}</ul>`:'<p>文件未声明连线输入；可能通过控件设置或隐藏输入获取内容。</p>'}</section><section><h3>输出：交出什么</h3>${n.outputs.length?`<ul>${n.outputs.map(p=>`<li><b>${esc(p.name)}</b>${cfTypeHTML(p.type)}</li>`).join('')}</ul>`:'<p>文件未列出输出端口。API 格式通常不带完整签名，不能据此断言“没有输出”。</p>'}</section></div>`;}
function cfEdgesHTML(n){const graph=cfGraph(),incoming=graph.edges.map((e,i)=>({...e,index:i})).filter(e=>e.target===n.id),outgoing=graph.edges.map((e,i)=>({...e,index:i})).filter(e=>e.source===n.id);function rows(edges,upstream){return edges.length?edges.map(e=>{const peer=graph.nodes.find(x=>x.id===(upstream?e.source:e.target));return `<button type="button" class="cf-wire-row" data-cf-edge="${e.index}"><span>${esc(upstream?(peer?.title||'缺失源节点'):n.title)}<small>${esc(e.sourceName||'输出槽 '+e.sourceSlot)}</small></span><span class="cf-wire-type">${esc(e.type)}<br><span aria-hidden="true">→</span></span><span>${esc(upstream?n.title:(peer?.title||'缺失目标节点'))}<small>${esc(e.targetName||'输入槽 '+e.targetSlot)}</small></span></button>`;}).join(''):'<p>本图没有声明这一路实体连线。还需考虑控件、子图边界与插件隐藏依赖。</p>';}
 return `<section class="cf-wiring"><h3>点一条线，看它为什么这样接</h3><h4>上游传入</h4>${rows(incoming,true)}<h4>交给下游</h4>${rows(outgoing,false)}</section>`;}
function cfEdgeHTML(){const g=cfGraph(),e=g?.edges[cfEdge];if(!e)return '';const a=g.nodes.find(n=>n.id===e.source),b=g.nodes.find(n=>n.id===e.target),def=cfTypes[e.type],specific=a?.type==='MiniMaxMusic3TextEncode'&&e.sourceName==='seconds'&&b?.type==='EmptyMiniMaxMusic3LatentAudio'?'这条线传该编码结果对应的时长（秒），用来建立配套音频 latent。它不是帧数、帧率或音频采样点数量。':'';return `<section class="cf-edge-detail" id="cf-edge-detail" tabindex="-1"><h3>这根线在传什么？</h3><p><b>${esc(a?.title||'未知源节点')}.${esc(e.sourceName||e.sourceSlot)}</b> → <b>${esc(b?.title||'未知目标节点')}.${esc(e.targetName||e.targetSlot)}</b></p><p>${cfTypeHTML(e.type)}</p><p>${esc(def?.[1]||'这个自定义类型还没有白话说明。先保留原类型名称，查节点包的接口契约，不把它擅自当成图片或模型。')}</p><p><b>下游为什么需要：</b>${esc(b?cfInfo(b).why:'目标节点缺失，无法确认用途。')}</p>${specific?`<p>${esc(specific)}</p>`:''}<p class="cf-note">类型来自文件声明。即使端口同名，也要核对模型、尺寸、单位与版本；静态解析不能证明实际运行成功。</p>${a?`<button class="text-button" data-cf-node="${esc(a.id)}">查看源节点</button>`:''}${b?`<button class="text-button" data-cf-node="${esc(b.id)}">查看目标节点</button>`:''}</section>`;}
function cfNodeDetailHTML(){const n=cfNode();if(!n)return '<p>请先选择一个节点。</p>';const info=cfInfo(n),source=cfSources[info.source],widgets=n.widgets,params=widgets&&typeof widgets==='object'?Object.entries(widgets):[];
 const variable=(n.type==='SetNode'||n.type==='GetNode')&&Array.isArray(widgets)?widgets[0]:null;
 const peers=variable?cfGraph().nodes.filter(x=>x.id!==n.id&&['SetNode','GetNode'].includes(x.type)&&Array.isArray(x.widgets)&&x.widgets[0]===variable):[];
 return `<section class="cf-node-detail" id="cf-node-detail" tabindex="-1"><div class="cf-detail-heading"><div><h2>${esc(info.name)}</h2><p>#${esc(n.id)} · <code>${esc(n.type)}</code></p></div>${n.subgraph?`<button class="secondary" data-cf-graph="${esc(n.subgraph)}">展开这个子图</button>`:''}</div>${cfModeHTML(n)}<p>${esc(info.does)}</p><p><b>放在这里的原因：</b>${esc(info.why)}</p>${cfPortsHTML(n)}${cfEdgesHTML(n)}${cfEdgeHTML()}<section class="cf-trap"><h3>最容易误解的地方</h3><p>${esc(info.trap)}</p></section>${peers.length?`<section><h3>同名 Set / Get 候选</h3><p>中转名：${esc(variable)}。这里只列同图同名候选，不当作已核实的运行时绑定。</p>${peers.map(p=>`<button class="text-button" data-cf-node="${esc(p.id)}">#${esc(p.id)} · ${esc(p.title)}</button>`).join('')}</section>`:''}<div class="cf-trace-actions"><button class="secondary" data-cf-trace="upstream">标记上游依赖</button><button class="secondary" data-cf-trace="downstream">标记下游影响</button><button class="text-button" data-cf-trace="clear">清除标记</button></div>${cfTrace.length?`<p role="status">已标记 ${cfTrace.length} 个实体连线可达节点。节点列表带标记；隐式中转和条件分支需另外核对。</p>`:''}${params.length?`<details class="cf-parameters"><summary>文件中的控件 / 参数值（只读）</summary><p>数组索引是保存位置，不保证能直接对应当前插件的参数名。不要把索引 0 自动称作强度或步数。</p><dl>${params.slice(0,40).map(([key,value])=>`<dt>${esc(key)}</dt><dd><pre>${esc(/key|token|secret|password|credential/i.test(key)?'（疑似凭据字段已隐藏）':typeof value==='string'?value.slice(0,4000):JSON.stringify(value)?.slice(0,4000)||'空')}</pre></dd>`).join('')}</dl></details>`:''}${source?`<p class="cf-source">说明参考：<a href="${source[1]}" target="_blank" rel="noopener noreferrer">${esc(source[0])}</a>。端口列表以本文件为准。</p>`:''}</section>`;}
function cfSampleNoticeHTML(sample){const teaching=sample.kind==='teaching',source=cfSources[sample.source];return `<details class="cf-audit"><summary>示例来源与使用范围</summary><p>${esc(sample.note)}</p>${teaching?`<p>本站原创结构图，节点接口参考公开文档。不会提供模型、参数或素材，也不是可运行原流。</p>${source?`<a href="${esc(source[1])}" target="_blank" rel="noopener noreferrer">${esc(source[0])}</a>`:''}`:`<a href="https://github.com/${sample.repo}/blob/main/${sample.path}" target="_blank" rel="noopener noreferrer">查看上游原始工作流</a><p>上游 Git blob：<code>${sample.sha}</code> · ${sample.license}。公开文件已移除所有提示词、参数值、便签、素材引用和附加元数据，只保留节点类型、端口与连线。不能直接用它运行生成；需要原参数时请在本地导入原文件。中文解释为本站独立编写。</p><a href="data/comfy/${sample.license==='MIT'?'LICENSE-ComfyOrg.txt':'LICENSE-ClipStream.txt'}" target="_blank">查看随附许可</a>`}</details>`;}
function cfModeHTML(n){if(n.boundary||n.annotation)return '';const text=n.mode===2?'本文件标记为不执行（mode 2）。不能因存在连线就认定该节点本次参与了运算。':n.mode===4?'本文件标记为绕过（mode 4）。跳过自身运算，具体直通规则由 Core 与插件决定。':'本文件为常规状态（mode '+n.mode+'）。本次是否实际执行仍需核对所需输出、分支与缓存。';return `<p class="cf-note"><b>节点状态：</b>${esc(text)} 静态图不是执行日志。</p>`;}
function cfInspectorHTML(){const g=cfGraph(),sample=cfSamples.find(s=>s.id===cfSampleId);return `<section class="cf-import"><div class="cf-import-controls"><label for="cf-sample">先读一个教学结构示例</label><div><select id="cf-sample">${cfSamples.map(s=>`<option value="${s.id}" ${s.id===cfSampleId?'selected':''}>${esc(s.title)}</option>`).join('')}</select><button class="secondary" data-cf-load>载入示例</button></div><label class="cf-file-label" for="cf-file">或导入你的工作流 JSON <input type="file" id="cf-file" accept=".json,application/json"></label><p class="cf-note">只在当前页面内存中解析，刷新后需重新导入；课程进度另行保存。不上传文件、不安装节点、不运行 GPU 任务。暂不读取 PNG 内嵌工作流；请从 ComfyUI 导出 JSON。最多 5 MiB。</p><details><summary>也可以粘贴界面 / API 格式 JSON</summary><label for="cf-json">工作流 JSON</label><textarea id="cf-json" rows="5" spellcheck="false" placeholder="粘贴工作流 nodes / links，或 API class_type / inputs"></textarea><button class="secondary" data-cf-parse>解析粘贴内容</button></details></div><div class="cf-import-explanation"><h2>先选一个方块，再追一根线</h2><p>主图太复杂时先看输出节点。UUID 可能是可展开子图；Set / Get 可能隐藏长线。</p><p>未知节点保留原始类型与端口，明确标为待核实。这里不会按名字假装知道它做了什么。</p>${resumeLesson()?.track==='comfy'?'<button class="text-button" data-learning-resume>回到上次课程 →</button>':''}</div></section>${cfLoading?'<p role="status">正在载入示例…</p>':''}${cfError?`<p class="cf-error" role="alert">${esc(cfError)}${cfDocument?' 上次成功解析的结果仍保留。':''}</p>`:''}${g?`<section class="cf-graph-summary"><div><b>${esc(cfOrigin)}</b><p>${esc(cfDocument.format)} · 全文件 ${cfDocument.totalNodes} 个节点（含便签，不含虚拟边界） / ${cfDocument.totalLinks} 条实体连接</p></div><label for="cf-graph">当前图 <select id="cf-graph">${cfDocument.graphs.map(graph=>`<option value="${esc(graph.id)}" ${graph.id===g.id?'selected':''}>${esc(graph.name)} · ${graph.nodes.filter(n=>!n.boundary).length} 节点</option>`).join('')}</select></label></section><div class="cf-inspector"><aside class="cf-palette"><label for="cf-node-query">找节点：名称 / ID / class_type</label><input id="cf-node-query" type="search" value="${esc(cfQuery)}" placeholder="例如：VAE、461、MotionContext"><div id="cf-node-list">${cfNodeListHTML()}</div></aside><div>${cfNodeDetailHTML()}</div></div><details class="cf-audit" ${g.warnings.length?'open':''}><summary>结构检查与解析边界 · ${g.warnings.length} 条提示</summary>${g.warnings.map(w=>`<p>${esc(w)}</p>`).join('')||'<p>未发现本解析器检查范围内的悬空连线、明显端口冲突或依赖环。仍需核对模型、素材与真实环境。</p>'}<p>API 执行图通常不包含完整输出签名。静态拓扑不等于执行日志，也不会验证模型权重或自定义节点是否安装。</p><details><summary>实体连接的拓扑顺序（仅辅助理解）</summary><p>${g.order.slice(0,120).map(id=>esc('#'+id)).join(' → ')}</p></details></details>${cfOrigin===sample?.title?cfSampleNoticeHTML(sample):''}`:'<section class="cf-empty"><h2>还没有解析结果</h2><p>载入教学结构示例，或选择本地原始 JSON。公开示例移除了全部提示词、参数与素材，不能直接运行生成。</p></section>'}`;}
function cfPracticeHTML(){const calc=cfCalculator,result=calc.result,target=cfWireTargets.find(t=>t[0]===cfWire.target),compatible=cfWire.result;return `<div class="cf-practice-grid"><section class="cf-panel"><h2>一根线，能不能这样接？</h2><p>先做类型这一层检查，再核对模型与数据语义。演示不会替你通关课程。</p><label for="cf-wire-source">上游交出什么<select id="cf-wire-source">${['MODEL','CONDITIONING','LATENT','IMAGE','AUDIO','VIDEO'].map(t=>`<option ${cfWire.source===t?'selected':''}>${t}</option>`).join('')}</select></label><label for="cf-wire-target">下游的输入入口<select id="cf-wire-target">${cfWireTargets.map(([name,t])=>`<option value="${name}" ${cfWire.target===name?'selected':''}>${name} · ${t}</option>`).join('')}</select></label><button class="primary" data-cf-wire>检查这条连接</button><div class="cf-feedback" id="cf-wire-feedback" role="status">${compatible===null?'先选择两端，再检查。':compatible?`类型层面匹配：${esc(cfWire.source)} → ${esc(target[1])}。还要核对模型、形状、单位和版本，不能仅凭这个结果宣布整条工作流能运行。`:`不能直接连接：上游是 ${esc(cfWire.source)}，下游需要 ${esc(target[1])}。${cfWire.source==='LATENT'&&target[1]==='IMAGE'?'本例先通过匹配的 VAE 解码为像素 IMAGE。':'先重新确认节点职责和需要的转换，不要只改端口颜色。'}`}</div></section><section class="cf-panel"><h2>帧数与时长怎么算？</h2><p>估算封装时长 = 实际帧数 ÷ fps。网格只对选定模型语境演示，不是全部视频模型的统一规则。</p><div class="cf-numeric"><label for="cf-frames">目标帧数<input id="cf-frames" type="number" min="1" max="100000" value="${calc.frames}"></label><label for="cf-fps">播放 fps<input id="cf-fps" type="number" min="0.1" max="240" step="0.1" value="${calc.fps}"></label></div><label for="cf-grid">帧数规则<select id="cf-grid">${[['none','只计算时长，不对齐'],['wan','Wan 示例：4n + 1'],['h3','H3 示例：17n + 5']].map(([v,s])=>`<option value="${v}" ${calc.grid===v?'selected':''}>${s}</option>`).join('')}</select></label><button class="secondary" data-cf-calculate>计算与解释</button><div class="cf-feedback" id="cf-calculator-feedback" role="status">${calc.error?esc(calc.error):result?`输入 ${result.requested} 帧 → 按所选规则向上对齐为 ${result.aligned} 帧；${result.aligned} ÷ ${result.fps} ≈ ${result.duration.toFixed(3)} 秒。${calc.grid==='h3'?' H3 原生生成以 24 fps 语境核对；这里更改播放 fps 不会改变模型本身的训练约束。':''}`:'尚未计算。试试固定帧数，只改变 fps，观察播放时长。'}</div><p class="cf-note">补帧需要生成新的中间帧。单独改 fps 不会产生这些帧；实际容器时长还受编码与时间戳影响。</p></section></div><section class="cf-panel cf-type-reference"><h2>把数据类型记成用途</h2><dl>${Object.entries(cfTypes).slice(0,9).map(([t,[name,description]])=>`<div><dt>${cfTypeHTML(t)}</dt><dd>${esc(description)}</dd></div>`).join('')}</dl></section>`;}
function cfHistoryHTML(){const matches=cfStudyTopics().map((r,i)=>({r,i})).filter(({r})=>r.join(' ').toLowerCase().includes(cfHistoryQuery.toLowerCase()));return `${matches.length} 条匹配 · 本站原创学习主题，不代表视频目录或逐字稿<table><thead><tr><th>学习主题</th><th>学什么</th><th>关联课程</th></tr></thead><tbody>${matches.slice(0,cfHistoryAll?100:8).map(({r,i})=>`<tr><td>${i+1}. ${esc(r[0])}</td><td>${esc(r[1])}</td><td><button class="text-button" data-hub="lesson" data-track="comfy" data-index="${hubCurriculum.comfy.findIndex(c=>c.id==='comfy-'+r[2])}">去学关联知识</button></td></tr>`).join('')}</tbody></table>${!matches.length?'<p>没有匹配主题，可清空搜索。</p>':''}`;}
function cfSourcesHTML(){return `<section class="cf-source-state"><h2>提取到哪一步，明确标出来</h2><p>当前课程对照公开节点定义、项目 README 和工作流连接结构独立编写。公开示例只保留教学所需的节点、端口与连线，已移除全部提示词、参数、便签和素材引用；不能作为可运行原流。</p><p>两个 b23 短链本次返回访问错误，最新完整分集目录与字幕尚未取得；不能标成“全部视频已提取”。</p><p>已补充经授权工作流的结构核对，并对照公开项目编写实战课。未成功读取的文件不作为讲解依据；私有原流、提示词和素材引用不公开。可在“工作流解析”本地导入自己的 JSON，查看真实端口。</p></section><section class="cf-panel"><h2>你提供的 UP 主线索</h2><div class="cf-source-rows"><article><h3>阿喵喵Az · minimax h3 小教程</h3><p>已核对部分公开简介与相关开源项目；完整分集字幕待继续核对。</p><a href="https://b23.tv/16fSvP6" target="_blank" rel="noopener noreferrer">打开你提供的合集</a></article><article><h3>不亦乐乎 · 用户提供合集</h3><p>保留原始链接；本轮尚未取得可核对的作者与分集目录。</p><a href="https://b23.tv/U6F8O5e" target="_blank" rel="noopener noreferrer">打开第二个合集</a></article><article><h3>其他 UP 主</h3><p>取得明确主页 / 视频地址后继续核对。未确认身份时，不擅自把不同账号合并到同一个合集。</p></article></div></section><section class="cf-panel"><h2>从学习主题进入课程</h2><p>下列主题来自本站原创课程。资料视频与课程通过公开知识点关联，不冒充视频逐字稿。</p><label for="cf-history-query">找主题<input id="cf-history-query" type="search" value="${esc(cfHistoryQuery)}" placeholder="接续、动作、数字人、二采"></label><div class="cf-table-wrap" id="cf-history-list">${cfHistoryHTML()}</div><button class="secondary" data-cf-history>${cfHistoryAll?'收起为前 8 条':'展开全部 '+cfStudyTopics().length+' 个学习主题'}</button></section><section class="cf-panel"><h2>本次核对过公开简介的视频</h2>${cfPublicVideos.map(v=>`<article class="cf-resource-row"><h3><a href="${v.url}" target="_blank" rel="noopener noreferrer">${esc(v.title)}</a></h3><p>${esc(v.status)}</p><button class="text-button" data-hub="lesson" data-track="comfy" data-index="${hubCurriculum.comfy.findIndex(c=>c.id==='comfy-'+v.lesson)}">先学这段需要的基础 →</button></article>`).join('')}</section><section class="cf-panel"><h2>配套开源项目</h2><p>按用途选择，先看原始说明与版本。本站没有安装这些节点到你的机器，也没有把运行时示例当成本机实测。</p>${cfResourceProjects.map(p=>`<article class="cf-resource-row"><h3><a href="${p.url}" target="_blank" rel="noopener noreferrer">${esc(p.name)}</a></h3><p>${esc(p.use)}</p><small>${esc(p.read)}</small></article>`).join('')}<p><a href="data/comfy/NOTICE.md" target="_blank">示例来源、文件版本与许可</a></p></section>`;}
function cfTroubleHTML(){return `<section class="cf-panel"><h2>先保留这几项证据</h2><p>失败节点的 ID / class_type、首条完整异常、模型和插件版本、输入尺寸 / 帧数、精度、失败阶段。缩小到最小流程，再一次改一个点。</p><button class="secondary" data-cf-pane="inspect">先解析工作流结构</button></section><section class="cf-trouble-list">${cfTroubles.map(([title,check,action])=>`<details><summary>${esc(title)}</summary><h3>先判断</h3><p>${esc(check)}</p><h3>再验证</h3><p>${esc(action)}</p></details>`).join('')}</section>`;}
function cfSubjectHTML(){return cfShell(cfPane==='route'?cfRouteHTML():cfPane==='inspect'?cfInspectorHTML():cfPane==='practice'?cfPracticeHTML():cfPane==='sources'?cfSourcesHTML():cfTroubleHTML());}
const cfPriorSubject=subjectHTML;
subjectHTML=function(){return hubSubject==='comfy'?cfSubjectHTML():cfPriorSubject();};
const cfPriorUnlocked=hubUnlocked;
hubUnlocked=function(track,i){return track==='comfy'?Number.isInteger(i)&&i>=0&&i<hubCurriculum.comfy.length:cfPriorUnlocked(track,i);};
const cfPriorNav=hubNav;
hubNav=function(){return cfPriorNav().replace('</nav>',`<button data-cf-open ${hubSubject==='comfy'&&['subject','hub-course'].includes(view)?'aria-current="page"':''}>ComfyUI 学习</button></nav>`);};
const cfPriorPage=pageContentHTML;
pageContentHTML=function(p){return cfPriorPage(p)+(p.comfySample?`<div class="cf-lesson-example"><button class="secondary" data-cf-example="${p.comfySample}">打开本课节点结构图 →</button><p>当前阅读与操作位置会保留。示例解析不替你执行生成，也不替你答题。</p></div>`:'');};
const cfPriorSnapshot=learningRouteSnapshot;
learningRouteSnapshot=function(){const r=cfPriorSnapshot();if(view==='subject'&&hubSubject==='comfy'){r.cfPane=cfPane;r.cfStage=cfStage;}return r;};
const cfPriorRestore=restoreLearningRoute;
restoreLearningRoute=async function(r){if(r?.view==='subject'&&r.subject==='comfy'){if(['route','inspect','practice','sources','trouble'].includes(r.cfPane))cfPane=r.cfPane;if(cfLessonRows.some(x=>x[1]===r.cfStage))cfStage=r.cfStage;}await cfPriorRestore(r);if(view==='subject'&&hubSubject==='comfy'&&cfPane==='inspect'&&!cfDocument&&!cfLoading)cfLoadSample(cfSampleId);};
document.addEventListener('click',async e=>{
 if(e.target.closest('[data-cf-open]'))return cfOpen();
 const pane=e.target.closest('[data-cf-pane]');if(pane)return cfOpen(pane.dataset.cfPane);
 const example=e.target.closest('[data-cf-example]');if(example)return cfOpen('inspect',example.dataset.cfExample);
 const stage=e.target.closest('[data-cf-stage]');if(stage){const s=[...new Set(cfLessonRows.map(r=>r[1]))][Number(stage.dataset.cfStage)];if(s){cfStage=s;render();}return;}
 if(e.target.closest('[data-cf-load]'))return cfLoadSample(document.getElementById('cf-sample').value);
 if(e.target.closest('[data-cf-parse]')){++cfLoadToken;cfLoading=false;try{cfAccept(document.getElementById('cf-json').value,'粘贴的本地工作流');}catch(err){cfError=err.message;}render();return;}
 const node=e.target.closest('[data-cf-node]');if(node&&cfGraph()?.nodes.some(n=>n.id===node.dataset.cfNode)){cfNodeId=node.dataset.cfNode;cfEdge=-1;render();document.getElementById('cf-node-detail')?.focus();if(window.innerWidth<700)document.getElementById('cf-node-detail')?.scrollIntoView({block:'start',behavior:'instant'});return;}
 const edge=e.target.closest('[data-cf-edge]');if(edge&&cfGraph()?.edges[Number(edge.dataset.cfEdge)]){cfEdge=Number(edge.dataset.cfEdge);render();document.getElementById('cf-edge-detail')?.focus();return;}
 const graph=e.target.closest('[data-cf-graph]');if(graph&&cfDocument?.graphs.some(g=>g.id===graph.dataset.cfGraph)){cfGraphId=graph.dataset.cfGraph;cfNodeId=cfGraph().nodes.find(n=>!n.annotation&&!n.boundary)?.id||cfGraph().nodes[0]?.id;cfEdge=-1;cfQuery='';cfTrace=[];render();return;}
 const trace=e.target.closest('[data-cf-trace]');if(trace&&cfGraph()){cfTrace=trace.dataset.cfTrace==='clear'?[]:ComfyLab.trace(cfGraph(),cfNodeId,trace.dataset.cfTrace);render();return;}
 if(e.target.closest('[data-cf-calculate]')){cfCalculator.frames=Number(document.getElementById('cf-frames').value);cfCalculator.fps=Number(document.getElementById('cf-fps').value);cfCalculator.grid=document.getElementById('cf-grid').value;try{cfCalculator.result=ComfyLab.framePlan(cfCalculator.frames,cfCalculator.fps,cfCalculator.grid);cfCalculator.error='';}catch(err){cfCalculator.result=null;cfCalculator.error=err.message;}render();return;}
 if(e.target.closest('[data-cf-wire]')){cfWire.source=document.getElementById('cf-wire-source').value;cfWire.target=document.getElementById('cf-wire-target').value;const target=cfWireTargets.find(t=>t[0]===cfWire.target);cfWire.result=!!target&&ComfyLab.compatible(cfWire.source,target[1]);render();return;}
 if(e.target.closest('[data-cf-history]')){cfHistoryAll=!cfHistoryAll;render();}
});
document.addEventListener('input',e=>{if(['cf-frames','cf-fps'].includes(e.target.id)){cfCalculator[e.target.id==='cf-frames'?'frames':'fps']=e.target.value;cfCalculator.result=null;cfCalculator.error='';const status=document.getElementById('cf-calculator-feedback');if(status)status.textContent='参数已更改，请重新计算。';}if(e.target.id==='cf-node-query'){cfQuery=e.target.value.slice(0,200);document.getElementById('cf-node-list').innerHTML=cfNodeListHTML();}if(e.target.id==='cf-history-query'){cfHistoryQuery=e.target.value.slice(0,200);document.getElementById('cf-history-list').innerHTML=cfHistoryHTML();}});
document.addEventListener('change',async e=>{if(e.target.id==='cf-sample'&&cfSamples.some(s=>s.id===e.target.value)){cfSampleId=e.target.value;}
if(['cf-wire-source','cf-wire-target'].includes(e.target.id)){cfWire[e.target.id==='cf-wire-source'?'source':'target']=e.target.value;cfWire.result=null;const status=document.getElementById('cf-wire-feedback');if(status)status.textContent='连接已更改，请重新检查。';}if(e.target.id==='cf-grid'){cfCalculator.grid=e.target.value;cfCalculator.result=null;cfCalculator.error='';const status=document.getElementById('cf-calculator-feedback');if(status)status.textContent='规则已更改，请重新计算。';}
 if(e.target.id==='cf-graph'&&cfDocument?.graphs.some(g=>g.id===e.target.value)){cfGraphId=e.target.value;cfNodeId=cfGraph().nodes.find(n=>!n.annotation&&!n.boundary)?.id||cfGraph().nodes[0]?.id;cfQuery='';cfTrace=[];cfEdge=-1;render();}
 if(e.target.id==='cf-file'){const file=e.target.files?.[0];if(!file)return;const token=++cfLoadToken;cfLoading=false;try{if(file.size>ComfyLab.LIMIT.bytes)throw Error('文件超过 5 MiB，请拆分工作流后导入。');const raw=await file.text();if(token!==cfLoadToken)return;cfAccept(raw,'本地文件：'+file.name);}catch(err){cfError=err.message;}render();}
});
const cfPriorTerms=decorateTerms;
decorateTerms=function(){if(view==='subject'&&hubSubject==='comfy')return;return cfPriorTerms();};
const cfPriorRender=render;
render=function(){cfPriorRender();if(view==='hub-course'&&hubTrack==='comfy'){const output=document.querySelector('.hub-terminal'),label=document.querySelector('.novice-output-label');if(label)label.textContent='本步判断结果';if(output&&!hubOutput)output.textContent='等待选择。这里只验证课程判断，不运行生图或生视频。';}};
render();
